import{_ as n,o as h,c as i,a6 as c}from"./chunks/framework.BfQ7p756.js";const u=JSON.parse('{"title":"Chương 0. Học và thi môn này thế nào","description":"","frontmatter":{"title":"Chương 0. Học và thi môn này thế nào"},"headers":[],"relativePath":"chuong-0.md","filePath":"chuong-0.md"}'),g={name:"chuong-0.md"};function a(o,t,r,e,d,l){return h(),i("div",null,[...t[0]||(t[0]=[c('<p class="eyebrow">Chương 0</p><h1 id="hoc-va-thi-mon-nay-the-nao" tabindex="-1">Học và thi môn này thế nào <a class="header-anchor" href="#hoc-va-thi-mon-nay-the-nao" aria-label="Permalink to &quot;Học và thi môn này thế nào&quot;">​</a></h1><p>Chương này không dạy C++. Nó trả lời một câu hỏi mà phần lớn sinh viên chỉ hiểu ra sau khi đã thi xong: <strong>bài thi thực hành đo cái gì</strong>, và vì sao nhiều bạn thấy lý thuyết rất ổn nhưng vào phòng thi lại không xong bài.</p><h2 id="_0-1-mot-su-that-nen-biet-truoc" tabindex="-1">0.1 Một sự thật nên biết trước <a class="header-anchor" href="#_0-1-mot-su-that-nen-biet-truoc" aria-label="Permalink to &quot;0.1 Một sự thật nên biết trước&quot;">​</a></h2><p>Ba lớp gần nhất của môn này có kết quả như sau:</p><table tabindex="0"><thead><tr><th>Thành phần đánh giá</th><th style="text-align:center;">Điểm trung bình</th><th style="text-align:center;">Số SV dưới 5</th></tr></thead><tbody><tr><td>Chuyên cần</td><td style="text-align:center;">9.3 – 9.4</td><td style="text-align:center;">1 / 147</td></tr><tr><td>Bài tập</td><td style="text-align:center;">8.0 – 8.9</td><td style="text-align:center;">12 / 147</td></tr><tr><td>Đồ án, thi cuối kỳ lý thuyết</td><td style="text-align:center;">8.0 – 8.3</td><td style="text-align:center;">0 / 147</td></tr><tr><td><span class="mau-gach"><strong>Thi thực hành trên máy</strong></span></td><td style="text-align:center;"><span class="mau-gach"><strong>4.8 – 6.6</strong></span></td><td style="text-align:center;"><span class="mau-gach"><strong>65 / 147</strong></span></td></tr></tbody></table><p>Mọi thành phần đều 8 – 9 điểm, riêng bài thi trên máy tụt xuống quanh mốc 5. Và điểm bài tập hằng tuần <strong>gần như không dự báo được</strong> điểm thi thực hành — hệ số tương quan chỉ 0.37.</p><div class="hop chu-y"><p class="hop-tieu-de">Điều đó nghĩa là gì</p><p>Làm được bài tập về nhà không chứng minh bạn sẽ làm được bài thi. Hai việc đó dùng hai kỹ năng khác nhau: đọc hiểu một lời giải đúng là một chuyện, tự viết ra nó trong 60 phút không có ai giúp là chuyện khác hẳn.</p><p>Cảm giác “mình hiểu rồi” khi đọc code của thầy là <strong>thật</strong> — nhưng nó là cảm giác nhận ra, không phải khả năng tạo ra. Chỉ có một cách phân biệt: đóng tài liệu lại và tự gõ.</p></div><h2 id="_0-2-đe-thi-đo-cai-gi-—-nhin-vao-thang-điem" tabindex="-1">0.2 Đề thi đo cái gì — nhìn vào thang điểm <a class="header-anchor" href="#_0-2-đe-thi-đo-cai-gi-—-nhin-vao-thang-điem" aria-label="Permalink to &quot;0.2 Đề thi đo cái gì — nhìn vào thang điểm&quot;">​</a></h2><p>Dưới đây là tổng hợp thang điểm của 12 đề thi thực hành gần nhất (hai học kỳ, hai ngành). Con số ở cột giữa là số đề có mục đó:</p><table tabindex="0"><thead><tr><th>Mục chấm</th><th style="text-align:center;">Có ở</th><th style="text-align:center;">Điểm</th></tr></thead><tbody><tr><td>Chia file rõ ràng (.h, .cpp, main.cpp, đúng tên)</td><td style="text-align:center;">12/12</td><td style="text-align:center;">2</td></tr><tr><td>Chương trình chạy đúng, test case hợp lý</td><td style="text-align:center;">12/12</td><td style="text-align:center;">2 – 3</td></tr><tr><td>Thiết kế đúng lớp, kế thừa đầy đủ</td><td style="text-align:center;">12/12</td><td style="text-align:center;">2</td></tr><tr><td>Dùng đúng hàm ảo và override, đa hình qua con trỏ</td><td style="text-align:center;">12/12</td><td style="text-align:center;">1 – 2</td></tr><tr><td>UML / comment rõ ràng</td><td style="text-align:center;">12/12</td><td style="text-align:center;">+2 thưởng</td></tr><tr><td>Bắt và xử lý đúng ngoại lệ</td><td style="text-align:center;">8/12</td><td style="text-align:center;">1</td></tr><tr><td>Tính trừu tượng</td><td style="text-align:center;">4/12</td><td style="text-align:center;">1</td></tr><tr><td>Tính đóng gói (private/protected + getter/setter)</td><td style="text-align:center;">4/12</td><td style="text-align:center;">1</td></tr><tr><td>Hàm khởi tạo đúng</td><td style="text-align:center;">4/12</td><td style="text-align:center;">1</td></tr></tbody></table><p><strong>Đọc kỹ hai dòng đầu.</strong></p><div class="hop chu-y"><p class="hop-tieu-de">Năm trên mười điểm không phải là hiểu OOP</p><p><strong>Chia file (2 điểm)</strong> là: tạo đủ file, đặt đúng tên, viết đúng <code>#ifndef</code>, để khai báo trong <code>.h</code> và cài đặt trong <code>.cpp</code>.</p><p><strong>Chạy đúng (3 điểm)</strong> là: biên dịch không lỗi, chạy không treo, in ra đúng từng dòng như đề yêu cầu.</p><p>Cả hai đều là <strong>thao tác</strong>, không phải tư duy. Ai luyện thì làm trong 10 phút, ai không luyện thì mất 40 phút và hết giờ trước khi kịp nghĩ tới thiết kế lớp. Đây là lý do thường gặp nhất của điểm 4 – 5.</p><p><strong>Và 2 điểm thưởng UML</strong> chỉ đòi vẽ một sơ đồ hộp — không cần viết dòng code nào. Bỏ trống 2 điểm này trong khi trung bình lớp là 4.8 là một quyết định rất đắt.</p></div><h2 id="_0-3-hinh-dang-mot-đe-thi-thuc-hanh" tabindex="-1">0.3 Hình dạng một đề thi thực hành <a class="header-anchor" href="#_0-3-hinh-dang-mot-đe-thi-thuc-hanh" aria-label="Permalink to &quot;0.3 Hình dạng một đề thi thực hành&quot;">​</a></h2><p>Mười hai đề gần nhất đều cùng một khuôn. Thời gian <strong>60 phút</strong>. Nội dung:</p><ol><li>Một đề bài mô tả 3–6 lớp bằng lời: lớp nào có thuộc tính gì, kế thừa ai, phương thức nào là thuần ảo.</li><li>Yêu cầu trong <code>main()</code>: tạo một <code>vector</code> hoặc mảng con trỏ lớp cha, thêm vài đối tượng lớp con, gọi một phương thức qua con trỏ đó.</li><li>Một khối “Kết quả kỳ vọng” in sẵn output từng dòng — đây vừa là yêu cầu vừa là bộ test để bạn tự kiểm tra.</li><li>Thang điểm in ngay trên đề. <strong>Bạn biết trước mình bị chấm bằng gì.</strong></li><li>Nén bài thành <code>&lt;MSSV&gt;_&lt;Ho ten khong dau&gt;.zip</code> đặt vào <code>C:\\OOP</code>.</li></ol><p>Nói cách khác: đề thi <strong>không có bất ngờ</strong>. Nó không hỏi thuật toán, không hỏi mẹo, không hỏi phần bạn chưa học. Nó yêu cầu đúng một việc — dựng một cây kế thừa nhỏ và cho nó chạy — và yêu cầu việc đó <strong>trong 60 phút, một mình</strong>.</p><h2 id="_0-4-vi-sao-ly-thuyet-on-ma-van-khong-xong-bai" tabindex="-1">0.4 Vì sao lý thuyết ổn mà vẫn không xong bài <a class="header-anchor" href="#_0-4-vi-sao-ly-thuyet-on-ma-van-khong-xong-bai" aria-label="Permalink to &quot;0.4 Vì sao lý thuyết ổn mà vẫn không xong bài&quot;">​</a></h2><p>Bốn nguyên nhân, theo thứ tự thường gặp:</p><div class="hop chu-y"><p><strong>1. Hết giờ vì thao tác chậm. </strong>Tạo 10 file, gõ header guard, gõ constructor, chạy <code>g++</code>, đọc lỗi liên kết. Nếu chưa thành phản xạ, riêng phần này đã ăn 40 trong 60 phút.</p><p><strong>2. Không đọc được thông báo lỗi. </strong>Lỗi đầu tiên của <code>g++</code> thường nói đúng chỗ sai, nhưng nếu chưa quen đọc thì sinh viên sửa mò và hỏng thêm.</p><p><strong>3. Chỉ nhớ hình dạng, không nhớ cách viết. </strong>Nhìn code có <code>virtual</code> thì hiểu ngay, nhưng tự gõ từ trang trắng thì không nhớ đặt <code>virtual</code> ở lớp nào, <code>override</code> ở lớp nào.</p><p><strong>4. Bỏ trống phần dễ. </strong>Không vẽ UML (mất 2 điểm thưởng), đặt sai tên file (mất tới 2 điểm), quên <code>virtual</code> ở destructor.</p></div><p>Cả bốn đều <strong>không</strong> chữa được bằng cách đọc thêm lý thuyết. Chúng chỉ chữa được bằng cách gõ.</p><h2 id="_0-5-cach-dung-giao-trinh-nay" tabindex="-1">0.5 Cách dùng giáo trình này <a class="header-anchor" href="#_0-5-cach-dung-giao-trinh-nay" aria-label="Permalink to &quot;0.5 Cách dùng giáo trình này&quot;">​</a></h2><p>Sách được chia theo đúng tỉ trọng của thang điểm, không theo thứ tự truyền thống của một sách C++:</p><table tabindex="0"><thead><tr><th>Chương</th><th>Nội dung</th><th>Điểm liên quan trong đề thi</th></tr></thead><tbody><tr><td>1</td><td>Công cụ, chia file, đọc lỗi biên dịch</td><td>2 (chia file) + phần lớn 3 (chạy đúng)</td></tr><tr><td>2</td><td>Lớp, đối tượng, UML</td><td>2 (thiết kế lớp) + 2 thưởng (UML)</td></tr><tr><td>3</td><td>Tính đóng gói</td><td>1</td></tr><tr><td>4</td><td>Tính kế thừa</td><td>2 (thiết kế, kế thừa)</td></tr><tr><td>5</td><td>Tính đa hình</td><td>1 – 2</td></tr><tr><td>6</td><td>Tính trừu tượng và giao diện</td><td>1</td></tr><tr><td>7</td><td>Xử lý ngoại lệ</td><td>1</td></tr><tr><td>8</td><td>Giải trọn một đề thi thật</td><td>toàn bộ</td></tr><tr><td>9</td><td>Luyện dịch UML thành chương trình — 6 bài bấm giờ</td><td>toàn bộ</td></tr></tbody></table><p>Mỗi chương mở đầu bằng khung <strong>“Chương này ăn điểm ở đâu trong đề thi”</strong> và kết thúc bằng phần <strong>“Tự kiểm tra”</strong> — một bài bạn phải gõ từ trang trắng, có bấm giờ.</p><h3 id="ba-quy-tac-neu-chi-nho-đuoc-ba-đieu" tabindex="-1">Ba quy tắc, nếu chỉ nhớ được ba điều <a class="header-anchor" href="#ba-quy-tac-neu-chi-nho-đuoc-ba-đieu" aria-label="Permalink to &quot;Ba quy tắc, nếu chỉ nhớ được ba điều&quot;">​</a></h3><div class="hop ghi-chu"><p class="hop-tieu-de">Ba quy tắc</p><p><strong>1. Gõ trước, đọc sau. </strong>Không mở đáp án khi chưa tự viết được ít nhất phần khai báo lớp. Đọc một lời giải đúng trước khi tự vật lộn là cách chắc chắn nhất để tưởng mình hiểu.</p><p><strong>2. Gõ, đừng chép. </strong>Chép–dán không luyện được ngón tay và không luyện được trí nhớ. Trong phòng thi bạn gõ, nên lúc học cũng phải gõ.</p><p><strong>3. Đọc lỗi đầu tiên, không đọc lỗi cuối cùng. </strong>Một lỗi cú pháp sinh ra hàng chục dòng thông báo. Chỉ lỗi đầu tiên là thật, sửa nó rồi biên dịch lại.</p></div><h3 id="he-thong-chay-xuyen-suot-sach-thu-vien" tabindex="-1">Hệ thống chạy xuyên suốt sách: thư viện <a class="header-anchor" href="#he-thong-chay-xuyen-suot-sach-thu-vien" aria-label="Permalink to &quot;Hệ thống chạy xuyên suốt sách: thư viện&quot;">​</a></h3><p>Mọi ví dụ trong sách đều xoay quanh <strong>một</strong> hệ thống mượn trả thư viện, lớn dần qua từng chương: chương 2 có lớp <code>Document</code> với ba thuộc tính, tới chương 7 nó thành một hệ thống có bốn loại tài liệu, phiếu mượn, hạn trả và xử lý lỗi.</p><p>Làm vậy để bạn trải nghiệm được điều quan trọng nhất của lập trình hướng đối tượng, thứ không giảng được bằng slide: <strong>mở rộng một hệ thống đang chạy mà không phá nó</strong>. Ở chương 6 bạn sẽ mở lại file mình viết ở chương 3 — nếu chương 3 thiết kế tốt thì chương 6 thêm một lớp mới không phải sửa gì, còn nếu thiết kế dở thì bạn sẽ phải trả giá. Đó là bài học đắt và đáng.</p><h2 id="_0-6-ban-đa-hoc-gi-o-tam-tuan-ly-thuyet" tabindex="-1">0.6 Bạn đã học gì ở tám tuần lý thuyết <a class="header-anchor" href="#_0-6-ban-đa-hoc-gi-o-tam-tuan-ly-thuyet" aria-label="Permalink to &quot;0.6 Bạn đã học gì ở tám tuần lý thuyết&quot;">​</a></h2><p>Sách này <strong>không</strong> dạy lại từ đầu. Nó đứng trên bộ slide lý thuyết bạn đã học. Bảng dưới đây cho biết mỗi chương của sách dựa vào tuần lý thuyết nào — nếu một chương thấy khó, hãy mở lại đúng tuần đó trước.</p><table tabindex="0"><thead><tr><th>Tuần lý thuyết</th><th>Bạn đã học</th><th>Sách dùng ở</th></tr></thead><tbody><tr><td>1</td><td>Giới thiệu OOP, procedural vs hướng đối tượng, tam giác P.I.E, mục tiêu OOP</td><td>Chương 0, 6</td></tr><tr><td>2</td><td>Hello world, tool-chain, ba loại lỗi (syntax / runtime / logic), các lỗi thường gặp</td><td><a href="./chuong-1.html">Chương 1</a></td></tr><tr><td>3</td><td>Hàm: prototype, nạp chồng, tham số mặc định, phạm vi biến, tham chiếu và truyền tham chiếu</td><td><a href="./chuong-1.html">Chương 1</a>, 2</td></tr><tr><td>4</td><td>Lớp và đối tượng, sơ đồ UML, constructor, danh sách khởi tạo, tách .h / .cpp, mảng đối tượng</td><td><a href="./chuong-1.html">Chương 1</a>, 2</td></tr><tr><td>5</td><td>Đóng gói, getter/setter, public/protected/private, this, thành viên static</td><td>Chương 3</td></tr><tr><td>6</td><td>Kế thừa, is-a, thứ tự constructor, truyền tham số cho lớp cha, redefining, friend</td><td>Chương 4</td></tr><tr><td>7</td><td>Đa hình, liên kết tĩnh và liên kết động, virtual, thuần ảo, destructor ảo, slicing</td><td>Chương 5</td></tr><tr><td>8</td><td>Lớp trừu tượng; ngoại lệ: throw/try/catch, thứ tự nhánh catch, what(), ném lại</td><td>Chương 6, 7</td></tr><tr><td>(phụ)</td><td>Bộ slide Pointer: con trỏ, mảng và con trỏ, truyền con trỏ vào hàm</td><td>Chương 3, 5</td></tr></tbody></table><h3 id="ba-cho-sach-phai-day-them-vi-bai-giang-chua-phu" tabindex="-1">Ba chỗ sách phải dạy thêm vì bài giảng chưa phủ <a class="header-anchor" href="#ba-cho-sach-phai-day-them-vi-bai-giang-chua-phu" aria-label="Permalink to &quot;Ba chỗ sách phải dạy thêm vì bài giảng chưa phủ&quot;">​</a></h3><div class="hop chu-y"><p class="hop-tieu-de">Đọc kỹ mục này — nó giải thích một phần điểm 4.8</p><p><strong>1. Cấp phát động </strong><code>new</code><strong> / </strong><code>delete</code><strong>. </strong>Không có trong bất kỳ slide lý thuyết nào (tuần 7 chỉ nhắc chữ “delete operator” khi nói về destructor ảo). Nhưng <strong>mọi đề thi đều dùng</strong> — <code>new Car(...)</code> rồi bỏ vào danh sách. Sách dạy ở mục 3.5.</p><p><strong>2. </strong><code>std::vector</code><strong>. </strong>Xuất hiện <strong>0 lần</strong> trong tám tuần slide. Nhưng đề thi ghi rõ “Tạo vector chứa Vehicle*”. Sách dạy ở mục 5.4.</p><p><strong>3. Lỗi liên kết. </strong>Bài giảng tuần 2 chia lỗi thành ba loại: cú pháp, lúc chạy, logic. Loại thứ tư — lỗi liên kết — chỉ xuất hiện khi bạn bắt đầu tách nhiều file, tức là từ tuần 4 trở đi. Sách dạy ở <a href="./chuong-1.html#_1-6-bon-loai-loi-va-cach-phan-biet">mục 1.6</a>.</p><p>Nếu bạn từng thấy hụt hẫng khi vào phòng thi, rất có thể ba chỗ này là lý do: chúng bị đòi hỏi nhưng chưa từng được giảng.</p></div><h3 id="đa-hoc-o-bai-giang-nhung-sach-khong-dung-toi" tabindex="-1">Đã học ở bài giảng nhưng sách không dùng tới <a class="header-anchor" href="#đa-hoc-o-bai-giang-nhung-sach-khong-dung-toi" aria-label="Permalink to &quot;Đã học ở bài giảng nhưng sách không dùng tới&quot;">​</a></h3><p>Để bạn khỏi thắc mắc vì sao chúng vắng mặt: thành viên <code>static</code> (tuần 5), <code>friend</code> class (tuần 6), kế thừa lai (hybrid) và kế thừa phân cấp (tuần 6), tiền/hậu điều kiện (tuần 5), bảo đảm an toàn ngoại lệ (tuần 8). Không mục nào trong số đó có mặt trong thang điểm của 12 đề thi gần nhất. Chúng vẫn đáng biết — chỉ là không phải thứ nên luyện trước ngày thi.</p><p>Một ngoại lệ: <code>friend</code> có được dùng đúng một lần trong sách, ở mục 5.6, để viết <code>operator&lt;&lt;</code>. Đó là ứng dụng thực tế phổ biến nhất của từ khoá này.</p><div class="hop chu-y"><p class="hop-tieu-de">Lưu ý về AI</p><p>Các công cụ AI viết được toàn bộ những bài trong sách này trong vài giây. Không ai cấm bạn dùng chúng để <strong>học</strong> — hỏi lại một khái niệm, nhờ giải thích một thông báo lỗi, nhờ chỉ ra chỗ sai trong code <strong>bạn đã tự viết</strong> — đó là cách dùng tốt.</p><p>Nhưng hãy nhìn lại bảng ở <a href="./chuong-0.html#_0-1-mot-su-that-nen-biet-truoc">mục 0.1</a>: trung bình thi thực hành là 4.8. AI không vào phòng thi cùng bạn. Nhờ nó làm hộ bài tập thì bạn vẫn nộp được bài, vẫn có điểm quá trình 9–10, và vẫn không qua nổi bài thi chiếm một nửa điểm môn.</p><p><strong>Điểm của môn này đến từ những gì bạn làm được khi không có nó.</strong></p></div>',39)])])}const p=n(g,[["render",a]]);export{u as __pageData,p as default};
